import { Badge } from '@/components/ui/badge';

describe('Badge', () => {
  it('renders a status span with default variant and classes', () => {
    render(<Badge>New</Badge>);

    const badge = screen.getByRole('status');
    expect(badge).toHaveTextContent('New');
    expect(badge).toHaveAttribute('data-variant', 'default');
    expect(badge).toHaveClass(
      'inline-flex',
      'items-center',
      'rounded-full',
      'px-2.5',
      'py-0.5',
      'text-xs',
      'font-medium',
      'bg-gray-100',
      'text-gray-800',
    );
  });

  it.each([
    ['success', 'bg-green-100', 'text-green-800'],
    ['warning', 'bg-amber-100', 'text-amber-800'],
    ['danger', 'bg-red-100', 'text-red-800'],
  ] as const)('renders %s colors', (variant, bg, text) => {
    render(<Badge variant={variant}>{variant}</Badge>);

    const badge = screen.getByRole('status');
    expect(badge).toHaveAttribute('data-variant', variant);
    expect(badge).toHaveClass(bg, text);
  });

  it('merges custom className so it wins and passes other props', () => {
    render(
      <Badge className="bg-blue-100 px-4" data-testid="pill" title="hello">
        Custom
      </Badge>,
    );

    const badge = screen.getByTestId('pill');
