describe('Command.envPrefix()', () => {
  test('when no prefix then no automatic environment variable', () => {
    const program = new commander.Command();
    process.env.FOO = 'env';
    program.addOption(new commander.Option('-f, --foo <value>'));
    program.parse([], { from: 'user' });
    assert.equal(program.opts().foo, undefined);
    delete process.env.FOO;
  });

  test('when get prefix before set then empty string', () => {
    const program = new commander.Command();
    assert.equal(program.envPrefix(), '');
  });

  test('when set prefix then get prefix', () => {
    const program = new commander.Command();
    program.envPrefix('MYAPP');
    assert.equal(program.envPrefix(), 'MYAPP');
  });

  test('when prefix and env defined then option from derived env', () => {
    const program = new commander.Command();
    process.env.MYAPP_FOO = 'env';
    program.envPrefix('MYAPP');
    program.addOption(new commander.Option('-f, --foo <value>'));
    program.parse([], { from: 'user' });
    assert.equal(program.opts().foo, 'env');
    delete process.env.MYAPP_FOO;
  });

  test('when prefix and env undefined then option undefined', () => {
    const program = new commander.Command();
    program.envPrefix('MYAPP');
    program.addOption(new commander.Option('-f, --foo <value>'));
    program.parse([], { from: 'user' });
    assert.equal(program.opts().foo, undefined);
  });

  test('when prefix and env defined and cli then option from cli', () => {
    const program = new commander.Command();
    process.env.MYAPP_FOO = 'env';
    program.envPrefix('MYAPP');
    program.addOption(new commander.Option('-f, --foo <value>'));
    program.parse(['--foo', 'cli'], { from: 'user' });
    assert.equal(program.opts().foo, 'cli');
    delete process.env.MYAPP_FOO;
  });

  test('when option name has dashes then derived env uses underscores', () => {
    const program = new commander.Command();
    process.env.MYAPP_PIZZA_TYPE = 'env';
    program.envPrefix('MYAPP');
    program.addOption(new commander.Option('--pizza-type <value>'));
    program.parse([], { from: 'user' });
    assert.equal(program.opts().pizzaType, 'env');
    delete process.env.MYAPP_PIZZA_TYPE;
  });

  test('when boolean flag then derived env sets true', () => {
    const program = new commander.Command();
    process.env.MYAPP_FOO = 'anything';
