import { Command, Option } from 'commander';
const program = new Command();

program.addOption(
  new Option('-p, --port <number>', 'specify port number')
    .default(80)
    .env('PORT'),
);
program.addOption(
  new Option('-c, --colour', 'turn on colour output').env('COLOUR'),
);
