const http = require('http')
const zlib = require('zlib')
const bodyParser = require('/home/user/TAILZU-BACKEND/tulmi/e2e/cache/work/val-body-parser-lang-raw-bBOQSW')

function server (parser) {
  return http.createServer((req, res) => {
    parser(req, res, (err) => {
      const out = {
        err: err ? { status: err.status, type: err.type, message: err.message } : null,
        rawBodyIsBuffer: Buffer.isBuffer(req.rawBody),
        rawBodyHex: Buffer.isBuffer(req.rawBody) ? req.rawBody.toString('hex') : null,
        rawBodyPresent: 'rawBody' in req,
        body: Buffer.isBuffer(req.body) ? req.body.toString('hex') : req.body
      }
      res.setHeader('content-type', 'application/json')
      res.end(JSON.stringify(out))
    })
  })
}

function req (srv, { body, headers = {} }, cb) {
  srv.listen(0, () => {
    const port = srv.address().port
    const r = http.request({ port, method: 'POST', headers: { 'content-type': 'text/plain', ...headers } }, (res) => {
      let d = ''
      res.on('data', c => { d += c })
      res.on('end', () => { srv.close(); cb(JSON.parse(d)) })
    })
    r.end(body)
  })
}

async function main () {
