const http = require('http')
const zlib = require('zlib')
const bodyParser = require('/home/user/TAILZU-BACKEND/tulmi/e2e/cache/work/val-body-parser-lang-raw-bBOQSW')

function server (parser) {
  return http.createServer((req, res) => {
    parser(req, res, (err) => {
      const out = {
        err: err ? { status: err.status, type: err.type, message: err.message } : null,
        rawBodyIsBuffer: Buffer.isBuffer(req.rawBody),
        rawBodyHex: Buffer.isBuffer(req.rawBody) ? req.rawBody.toString('hex') : null,
        rawBodyPresent: 'rawBody' in req,
        body: Buffer.isBuffer(req.body) ? req.body.toString('hex') : req.body
      }
      res.setHeader('content-type', 'application/json')
      res.end(JSON.stringify(out))
    })
  })
}

function req (srv, { body, headers = {} }, cb) {
  srv.listen(0, () => {
    const port = srv.address().port
    const r = http.request({ port, method: 'POST', headers: { 'content-type': 'text/plain', ...headers } }, (res) => {
      let d = ''
      res.on('data', c => { d += c })
      res.on('end', () => { srv.close(); cb(JSON.parse(d)) })
    })
    r.end(body)
  })
}

async function main () {
  // latin1 text: 0xE9 is é in latin1
  const s1 = server(bodyParser.text({ rawBody: true }))
  await new Promise(res => req(s1, {
    body: Buffer.from([0xE9, 0x41]),
    headers: { 'content-type': 'text/plain; charset=latin1' }
  }, out => { console.log('text latin1 rawBody=true', out); res() }))

  // rawBody absent when not set
  const s2 = server(bodyParser.text())
  await new Promise(res => req(s2, { body: 'hi' }, out => { console.log('text default', out); res() }))

  // rawBody=false
  const s3 = server(bodyParser.text({ rawBody: false }))
  await new Promise(res => req(s3, { body: 'hi' }, out => { console.log('text rawBody=false', out); res() }))

  // parse failure still has bytes
  const s4 = server(bodyParser.json({ rawBody: true }))
  await new Promise(res => req(s4, { body: '{bad', headers: { 'content-type': 'application/json' } }, out => { console.log('json parse fail', out); res() }))

  // gzip
  const gz = zlib.gzipSync(Buffer.from('hello'))
  const s5 = server(bodyParser.text({ rawBody: true }))
  await new Promise(res => req(s5, { body: gz, headers: { 'content-type': 'text/plain', 'content-encoding': 'gzip' } }, out => { console.log('text gzip', out); res() }))

  // verify + rawBody
  const s6 = server(bodyParser.raw({ rawBody: true, verify: (r) => { r.verifiedLen = r.rawBody.length } }))
  await new Promise(res => req(s6, { body: Buffer.from([1, 2, 3]) }, out => { console.log('raw verify+rawBody', out); res() }))
}
