  // verify + rawBody
  const s6 = server(bodyParser.raw({ rawBody: true, verify: (r) => { r.verifiedLen = r.rawBody.length } }))
  await new Promise(res => req(s6, { body: Buffer.from([1, 2, 3]) }, out => { console.log('raw verify+rawBody', out); res() }))
}
