  const _bodyParser = typeof opts !== 'function'
    ? bodyParser.text(opts)
    : opts

  return http.createServer(function (req, res) {
    _bodyParser(req, res, function (err) {
      res.statusCode = err ? (err.status || 500) : 200
      res.end(err
        ? ('[' + err.type + '] ' + err.message)
        : (JSON.stringify(req.body) || typeof req.body)
      )
    })
  })
}

function createRawBodyServer (opts) {
  const _bodyParser = bodyParser.text(opts)

  return http.createServer(function (req, res) {
    _bodyParser(req, res, function (err) {
      res.statusCode = err ? (err.status || 500) : 200
      res.setHeader('Content-Type', 'application/json')
      res.end(JSON.stringify({
        error: err ? ('[' + err.type + '] ' + err.message) : null,
        has: 'rawBody' in req,
        isBuffer: Buffer.isBuffer(req.rawBody),
        rawBody: Buffer.isBuffer(req.rawBody) ? req.rawBody.toString('hex') : null,
        body: req.body
      }))
    })
  })
}
