  // rawBody=false
  const s3 = server(bodyParser.text({ rawBody: false }))
  await new Promise(res => req(s3, { body: 'hi' }, out => { console.log('text rawBody=false', out); res() }))

  // parse failure still has bytes
  const s4 = server(bodyParser.json({ rawBody: true }))
