  }, out => { console.log('text latin1 rawBody=true', out); res() }))

  // rawBody absent when not set
  const s2 = server(bodyParser.text())
  await new Promise(res => req(s2, { body: 'hi' }, out => { console.log('text default', out); res() }))

  // rawBody=false
  const s3 = server(bodyParser.text({ rawBody: false }))
  await new Promise(res => req(s3, { body: 'hi' }, out => { console.log('text rawBody=false', out); res() }))

  // parse failure still has bytes
  const s4 = server(bodyParser.json({ rawBody: true }))
  await new Promise(res => req(s4, { body: '{bad', headers: { 'content-type': 'application/json' } }, out => { console.log('json parse fail', out); res() }))

