  return new Promise((resolve, reject) => {
    server.listen(0, function () {
      const port = server.address().port
      const req = http.request({ port, method: opts.method || 'POST', path: '/', headers: opts.headers || {} }, function (res) {
        const chunks = []
        res.on('data', (c) => chunks.push(c))
        res.on('end', function () {
          server.close()
          resolve({ status: res.statusCode, headers: res.headers, buffer: Buffer.concat(chunks), text: Buffer.concat(chunks).toString('utf8') })
        })
      })
      req.on('error', function (e) { server.close(); reject(e) })
      if (opts.body) req.write(opts.body)
      req.end()
    })
  })
}

